#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Deploys lcmp-mcp to Azure Container Apps behind Entra ID; docs/deploy-azure.md explains each stage.
# Every stage looks up what already exists first, so re-running is safe and resumes where it stopped.
#
#   scripts/deploy-azure.sh                     walk through every stage (create or check)
#   scripts/deploy-azure.sh status              read-only report: resources, secrets vs .env, logs, live checks
#   scripts/deploy-azure.sh update              build the image for package.json's version and roll the app to it
#   scripts/deploy-azure.sh credentials CODE    store a country's username/password again, then reload the app
#   scripts/deploy-azure.sh restart             restart the running revision
#
# Names come from scripts/azure.conf (override with AZURE_CONF=path). Run from the repo root in Git Bash.

export MSYS_NO_PATHCONV=1   # Git Bash: keep /subscriptions/... arguments intact
CONF="${AZURE_CONF:-scripts/azure.conf}"
AZ_CLI_APP_ID=04b07795-8ddb-461a-bbee-02f9e1bf7b46   # Microsoft's fixed client ID for the Azure CLI
BASE_URL=https://marketplace.logicom.net/SimpleAPI/SimpleAPIService.svc/rest
PROVIDERS=(Microsoft.App Microsoft.OperationalInsights Microsoft.ContainerRegistry Microsoft.KeyVault Microsoft.ManagedIdentity)

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }
# azq ARGS: a read-only az lookup. Prints nothing, and succeeds, when the thing doesn't exist.
azq() { az "$@" 2>/dev/null | tr -d '\r' || true; }
lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }
upper() { printf '%s' "$1" | tr '[:lower:]' '[:upper:]'; }
codes() { printf '%s\n' "${MARKETPLACES//,/ }" | tr ' ' '\n' | grep -v '^$' || true; }
# envval KEY: KEY from .env, parsed exactly as the server parses it (node --env-file).
envval() {
  [[ -f .env ]] || return 0
  node --env-file=.env -e 'process.stdout.write(process.env[process.argv[1]] ?? "")' "$1" 2>/dev/null || true
}
# report LABEL VALUE [MISSING_HINT]: one aligned status line; an empty VALUE prints the hint.
report() {
  if [[ -n "$2" ]]; then printf '  %-20s %s\n' "$1" "$2"
  else printf '  %-20s %s%s%s\n' "$1" "$YELLOW" "${3:-missing}" "$RESET"; fi
}

load_conf() {
  [[ -f package.json && -f Dockerfile ]] || die "Run this from the repo root."
  [[ -f "$CONF" ]] || die "Config $CONF not found."
  # shellcheck source=azure.conf
  source "$CONF"
  local v; for v in SUBSCRIPTION RG APP ENV_NAME LAW IDENTITY ACR KV API_APP_NAME CLIENT_APP_NAME MARKETPLACES; do
    [[ -n "${!v:-}" ]] || die "$v is empty in $CONF."
  done
  local t; for t in az node curl; do command -v "$t" >/dev/null 2>&1 || die "$t not found on PATH."; done
}

sign_in() {
  az account show -o none 2>/dev/null || az login -o none
  az account set --subscription "$SUBSCRIPTION" || die "Can't select subscription \"$SUBSCRIPTION\"."
}

# resolve: look up everything earlier stages may have created. Missing things stay empty.
resolve() {
  IMAGE_TAG=$(node -p "require('./package.json').version")
  IMAGE="$ACR.azurecr.io/lcmp-mcp:$IMAGE_TAG"
  TENANT_ID=$(azq account show --query tenantId -o tsv)
  LOC=$(azq group show -n "$RG" --query location -o tsv)
  ME=$(azq ad signed-in-user show --query id -o tsv)
  local n; n=$(azq ad app list --display-name "$API_APP_NAME" --query "length(@)" -o tsv)
  [[ "${n:-0}" -le 1 ]] || warn "$n app registrations are named \"$API_APP_NAME\"; using the first. Delete the extras."
  API_APP_ID=$(azq ad app list --display-name "$API_APP_NAME" --query "[0].appId" -o tsv)
  API_OBJ_ID=""; API_SP_ID=""; ROLE_ID=""; SCOPE_ID=""
  if [[ -n "$API_APP_ID" ]]; then
    API_OBJ_ID=$(azq ad app show --id "$API_APP_ID" --query id -o tsv)
    API_SP_ID=$(azq ad sp show --id "$API_APP_ID" --query id -o tsv)
    ROLE_ID=$(azq ad app show --id "$API_APP_ID" --query "appRoles[?value=='LCMP.Read'].id | [0]" -o tsv)
    SCOPE_ID=$(azq ad app show --id "$API_APP_ID" --query "api.oauth2PermissionScopes[?value=='access_as_user'].id | [0]" -o tsv)
  fi
  CLIENT_APP_ID=$(azq ad app list --display-name "$CLIENT_APP_NAME" --query "[0].appId" -o tsv)
  CLIENT_SP_ID=""
  [[ -z "$CLIENT_APP_ID" ]] || CLIENT_SP_ID=$(azq ad sp show --id "$CLIENT_APP_ID" --query id -o tsv)
  KV_ID=$(azq keyvault show -n "$KV" --query id -o tsv)
  ACR_ID=$(azq acr show -n "$ACR" --query id -o tsv)
  IDENTITY_ID=$(azq identity show -g "$RG" -n "$IDENTITY" --query id -o tsv)
  IDENTITY_PRINCIPAL=$(azq identity show -g "$RG" -n "$IDENTITY" --query principalId -o tsv)
  FQDN=$(azq containerapp show -g "$RG" -n "$APP" --query properties.configuration.ingress.fqdn -o tsv)
}

# ensure_role ROLE PRINCIPAL_ID PRINCIPAL_TYPE SCOPE: assigns an Azure role unless it's there.
# Succeeds only when it assigned one, so callers know to wait for it to apply.
ensure_role() {
  local n; n=$(azq role assignment list --assignee "$2" --scope "$4" --query "[?roleDefinitionName=='$1'] | length(@)" -o tsv)
  if [[ "${n:-0}" -gt 0 ]]; then ok "$1 already assigned"; return 1; fi
  az role assignment create --role "$1" --assignee-object-id "$2" --assignee-principal-type "$3" --scope "$4" -o none
  ok "assigned $1"
}

# grant_app_role PRINCIPAL_ID LABEL: gives a user or group LCMP.Read on the API, unless it already has it.
grant_app_role() {
  local have; have=$(azq rest --method GET --uri "https://graph.microsoft.com/v1.0/servicePrincipals/$API_SP_ID/appRoleAssignedTo" \
    --query "value[?principalId=='$1'] | length(@)" -o tsv)
  if [[ "${have:-0}" -gt 0 ]]; then ok "$2 already has LCMP.Read"; return; fi
  az rest --method POST --uri "https://graph.microsoft.com/v1.0/servicePrincipals/$API_SP_ID/appRoleAssignedTo" \
    --headers Content-Type=application/json \
    --body "{\"principalId\":\"$1\",\"resourceId\":\"$API_SP_ID\",\"appRoleId\":\"$ROLE_ID\"}" -o none
  ok "gave $2 LCMP.Read"
}

# store_credentials CODE: writes a country's username and password to Key Vault, from .env or typed in.
store_credentials() {
  local code="$1" c user pass
  c=$(lower "$code")
  user=$(envval "LCMP_${code}_USERNAME"); pass=$(envval "LCMP_${code}_PASSWORD")
  if [[ -n "$user" && -n "$pass" ]]; then
    say "Using LCMP_${code}_USERNAME and LCMP_${code}_PASSWORD from .env."
  else
    say "$code isn't in .env: type its MCP API user (paste with Shift+Insert or right-click)."
    read -rp  "  $code username: " user
    read -rsp "  $code password: " pass; printf '\n'
  fi
  user=${user//[[:cntrl:]]/}; pass=${pass//[[:cntrl:]]/}   # drop invisible characters, e.g. the ^V Ctrl+V types
  [[ -n "$user" && -n "$pass" ]] || die "Empty username or password for $code."
  az keyvault secret set --vault-name "$KV" -n "lcmp-$c-username" --value="$user" -o none
  az keyvault secret set --vault-name "$KV" -n "lcmp-$c-password" --value="$pass" -o none
  ok "stored $code credentials in $KV"
  note "Its API user must be on the $code marketplace's AllowList (the Logicom team adds it), or logins from Azure fail."
}

# app_secret_args / app_env_args: Key Vault references and env vars for every country in MARKETPLACES.
app_secret_args() {
  local code c; for code in $(codes); do c=$(lower "$code")
    printf '%s\n' "$c-user=keyvaultref:https://$KV.vault.azure.net/secrets/lcmp-$c-username,identityref:$IDENTITY_ID"
    printf '%s\n' "$c-pass=keyvaultref:https://$KV.vault.azure.net/secrets/lcmp-$c-password,identityref:$IDENTITY_ID"
  done
}
app_env_args() {
  local code c; for code in $(codes); do c=$(lower "$code")
    printf '%s\n' "LCMP_${code}_USERNAME=secretref:$c-user" "LCMP_${code}_PASSWORD=secretref:$c-pass"
  done
  printf '%s\n' "LCMP_MARKETPLACES=$MARKETPLACES"
}

restart_app() {
  local rev; rev=$(azq containerapp revision list -g "$RG" -n "$APP" --query "[?properties.active].name | [0]" -o tsv)
  [[ -n "$rev" ]] || die "No active revision of $APP."
  az containerapp revision restart -g "$RG" -n "$APP" --revision "$rev" -o none
  ok "restarted $rev"
}

# check_endpoint: health, 401 without a token, then a ping per country with your token.
check_endpoint() {
  [[ -n "$FQDN" ]] || { report "endpoint" "" "missing (stage 9)"; return 0; }
  report "endpoint" "https://$FQDN/mcp"
  report "/health" "$(curl -s --max-time 60 "https://$FQDN/health" || true)" "no answer: see the logs"
  report "no token" "HTTP $(curl -s -o /dev/null -w '%{http_code}' --max-time 30 -X POST "https://$FQDN/mcp" || true) (401 expected)"
  local token code out body
  token=$(azq account get-access-token --scope "api://$API_APP_ID/access_as_user" --query accessToken -o tsv)
  [[ -n "$token" ]] || { report "your token" "" "can't get one: do you hold LCMP.Read? (stage 3)"; return 0; }
  for code in $(codes); do
    body='{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"ping","arguments":{"marketplace":"'"$code"'"}}}'
    out=$(curl -s --max-time 120 "https://$FQDN/mcp" -H "Authorization: Bearer $token" \
      -H "Content-Type: application/json" -H "Accept: application/json, text/event-stream" -d "$body" || true)
    if [[ "$out" == *"session is valid"* ]]; then report "ping $code" "connected"
    elif [[ "$out" == *"sign you in"* ]]; then report "ping $code" "" "login refused: AllowList (Logicom team) or wrong credentials"
    else report "ping $code" "" "${out:0:200}"; fi
  done
}

# ── Stages of the walkthrough ─────────────────────────────────────────────

do_prereqs() {
  say "Signs you in, selects the subscription, and registers the Azure resource providers."
  sign_in; ok "subscription $SUBSCRIPTION"
  az extension show -n containerapp -o none 2>/dev/null || az extension add -n containerapp --upgrade -o none
  ok "containerapp CLI extension"
  local p; for p in "${PROVIDERS[@]}"; do
    [[ "$(azq provider show -n "$p" --query registrationState -o tsv)" == Registered ]] || az provider register -n "$p" --wait
  done
  ok "resource providers registered"
  resolve
  [[ -n "$LOC" ]] || die "Resource group $RG not found in this subscription."
  ok "resource group $RG in $LOC, image tag $IMAGE_TAG"
}

do_api_app() {
  say "The registration that represents the server: role LCMP.Read, scope access_as_user, v2 tokens."
  if [[ -z "$API_APP_ID" ]]; then
    API_APP_ID=$(az ad app create --display-name "$API_APP_NAME" --sign-in-audience AzureADMyOrg --query appId -o tsv | tr -d '\r')
    API_OBJ_ID=$(az ad app show --id "$API_APP_ID" --query id -o tsv | tr -d '\r')
    ok "created \"$API_APP_NAME\" ($API_APP_ID)"
  else ok "\"$API_APP_NAME\" exists ($API_APP_ID)"; fi

  if [[ -z "$ROLE_ID" || -z "$SCOPE_ID" ]]; then
    [[ -n "$ROLE_ID" ]]  || ROLE_ID=$(node -e "console.log(crypto.randomUUID())")
    [[ -n "$SCOPE_ID" ]] || SCOPE_ID=$(node -e "console.log(crypto.randomUUID())")
    local body
    body=$(API_APP_ID="$API_APP_ID" SCOPE_ID="$SCOPE_ID" ROLE_ID="$ROLE_ID" node -e '
      const e = process.env, text = "Read-only access to the LCMP Marketplace through the MCP server.";
      console.log(JSON.stringify({
        identifierUris: ["api://" + e.API_APP_ID],
        api: { requestedAccessTokenVersion: 2, oauth2PermissionScopes: [{
          id: e.SCOPE_ID, value: "access_as_user", type: "User", isEnabled: true,
          adminConsentDisplayName: "Use the LCMP MCP server", adminConsentDescription: text,
          userConsentDisplayName: "Use the LCMP MCP server", userConsentDescription: text }] },
        appRoles: [{ id: e.ROLE_ID, value: "LCMP.Read", isEnabled: true, allowedMemberTypes: ["User"],
          displayName: "LCMP MCP read access", description: "Can use the read-only LCMP MCP server." }] }));')
    az rest --method PATCH --uri "https://graph.microsoft.com/v1.0/applications/$API_OBJ_ID" \
      --headers Content-Type=application/json --body "$body" -o none
    ok "added role LCMP.Read and scope access_as_user"
  else ok "role LCMP.Read and scope access_as_user present"; fi

  # Lets `az account get-access-token` request tokens for the API, for the checks in stage 10.
  local pre; pre=$(azq ad app show --id "$API_APP_ID" --query "api.preAuthorizedApplications[?appId=='$AZ_CLI_APP_ID'] | length(@)" -o tsv)
  if [[ "${pre:-0}" -eq 0 ]]; then
    az rest --method PATCH --uri "https://graph.microsoft.com/v1.0/applications/$API_OBJ_ID" \
      --headers Content-Type=application/json \
      --body "{\"api\":{\"preAuthorizedApplications\":[{\"appId\":\"$AZ_CLI_APP_ID\",\"delegatedPermissionIds\":[\"$SCOPE_ID\"]}]}}" -o none
    ok "pre-authorised the Azure CLI"
  else ok "Azure CLI pre-authorised"; fi

  [[ -n "$API_SP_ID" ]] || API_SP_ID=$(az ad sp create --id "$API_APP_ID" --query id -o tsv | tr -d '\r')
  # Assignment required: people without the role can't even get a token.
  [[ "$(azq ad sp show --id "$API_APP_ID" --query appRoleAssignmentRequired -o tsv)" == true ]] \
    || az ad sp update --id "$API_SP_ID" --set appRoleAssignmentRequired=true
  ok "service principal $API_SP_ID requires role assignment"
}

do_access() {
  say "Gives LCMP.Read to you (for the checks in stage 10) and to the support team's group."
  note "Only direct members of the group get the role. Group assignment needs Entra ID P1."
  [[ -n "${ACCESS_GROUP:-}" ]] || ask ACCESS_GROUP "Group to give LCMP.Read (Enter to skip):"
  local gid=""
  if [[ -n "$ACCESS_GROUP" ]]; then
    gid=$(azq ad group show --group "$ACCESS_GROUP" --query id -o tsv)
    [[ -n "$gid" ]] || die "Group \"$ACCESS_GROUP\" not found."
    grant_app_role "$gid" "\"$ACCESS_GROUP\""
  fi
  if [[ -n "$gid" && "$(azq ad group member check --group "$gid" --member-id "$ME" --query value -o tsv)" == true ]]; then
    ok "you get LCMP.Read through \"$ACCESS_GROUP\""
  else grant_app_role "$ME" "you"; fi
  note "Manage access later in Entra admin centre → Enterprise applications → $API_APP_NAME → Users and groups."
}

do_client_app() {
  say "The registration Copilot Studio signs users in with, consented to the access_as_user scope."
  if [[ -z "$CLIENT_APP_ID" ]]; then
    CLIENT_APP_ID=$(az ad app create --display-name "$CLIENT_APP_NAME" --sign-in-audience AzureADMyOrg --query appId -o tsv | tr -d '\r')
    ok "created \"$CLIENT_APP_NAME\" ($CLIENT_APP_ID)"
  else ok "\"$CLIENT_APP_NAME\" exists ($CLIENT_APP_ID)"; fi
  [[ -n "$CLIENT_SP_ID" ]] || CLIENT_SP_ID=$(az ad sp create --id "$CLIENT_APP_ID" --query id -o tsv | tr -d '\r')

  local n; n=$(azq ad app show --id "$CLIENT_APP_ID" --query "requiredResourceAccess[?resourceAppId=='$API_APP_ID'] | length(@)" -o tsv)
  [[ "${n:-0}" -gt 0 ]] || az ad app permission add --id "$CLIENT_APP_ID" --api "$API_APP_ID" --api-permissions "$SCOPE_ID=Scope" 2>/dev/null
  ok "requests access_as_user"

  # Admin consent for every user. Entra can take a minute to see a new service principal, so retry.
  local tries=0 grants
  while :; do
    grants=$(azq rest --method GET --uri "https://graph.microsoft.com/v1.0/servicePrincipals/$CLIENT_SP_ID/oauth2PermissionGrants" \
      --query "value[?resourceId=='$API_SP_ID'] | length(@)" -o tsv)
    [[ "${grants:-0}" -eq 0 ]] || break
    (( tries++ < 5 )) || die "Admin consent failed. Run: az ad app permission grant --id $CLIENT_APP_ID --api $API_APP_ID --scope access_as_user"
    az ad app permission grant --id "$CLIENT_APP_ID" --api "$API_APP_ID" --scope access_as_user -o none 2>/dev/null || sleep 20
  done
  ok "admin consent granted"

  local ends; ends=$(azq ad app show --id "$CLIENT_APP_ID" --query "passwordCredentials[0].endDateTime" -o tsv)
  if [[ -n "$ends" ]]; then ok "client secret exists, expires ${ends%%T*}"; return 0; fi
  local secret; secret=$(az ad app credential reset --id "$CLIENT_APP_ID" --display-name copilot-studio --years 1 --query password -o tsv | tr -d '\r')
  warn "Client secret, shown only now. Save it in your password manager for stage 11:"
  printf '\n    %s%s%s\n\n' "$BOLD" "$secret" "$RESET"
  note "It expires in a year: renew with az ad app credential reset --id $CLIENT_APP_ID --append, then update Copilot Studio."
  pause "Saved it? Press Enter."
}

do_hosting() {
  say "Log workspace, Container Apps environment and registry."
  if [[ -z "$(azq monitor log-analytics workspace show -g "$RG" -n "$LAW" --query id -o tsv)" ]]; then
    az monitor log-analytics workspace create -g "$RG" -n "$LAW" -l "$LOC" -o none; ok "created workspace $LAW"
  else ok "workspace $LAW exists"; fi

  local state; state=$(azq containerapp env show -g "$RG" -n "$ENV_NAME" --query properties.provisioningState -o tsv)
  if [[ -z "$state" ]]; then
    note "Creating the environment takes a few minutes (10-15 if a deleted one is still going)."
    local law_id law_key
    law_id=$(azq monitor log-analytics workspace show -g "$RG" -n "$LAW" --query customerId -o tsv)
    law_key=$(azq monitor log-analytics workspace get-shared-keys -g "$RG" -n "$LAW" --query primarySharedKey -o tsv)
    az containerapp env create -g "$RG" -n "$ENV_NAME" -l "$LOC" --logs-workspace-id "$law_id" --logs-workspace-key "$law_key" -o none
    ok "created environment $ENV_NAME"
  elif [[ "$state" == Succeeded ]]; then ok "environment $ENV_NAME exists"
  else warn "environment $ENV_NAME is $state: wait for Succeeded, then re-run."; exit 1; fi

  if [[ -z "$ACR_ID" ]]; then
    az acr create -g "$RG" -n "$ACR" --sku Basic -l "$LOC" -o none || die "Can't create registry $ACR: pick another ACR name in $CONF."
    ACR_ID=$(azq acr show -n "$ACR" --query id -o tsv); ok "created registry $ACR"
  else ok "registry $ACR exists"; fi
}

do_image() {
  say "The server image for version $IMAGE_TAG (from package.json)."
  if azq acr repository show-tags -n "$ACR" --repository lcmp-mcp -o tsv | grep -qx "$IMAGE_TAG"; then
    ok "image lcmp-mcp:$IMAGE_TAG exists"
    if [[ -z "$FQDN" ]]; then
      confirm "Rebuild it from your checkout? Nothing runs it yet, so overwriting is safe." && build_image
    else note "To ship code changes, bump version in package.json, then run: $0 update"; fi
  else build_image; fi
}

build_image() {
  note "Azure builds the image from your checkout; .dockerignore keeps .env out of the upload."
  az acr build -r "$ACR" -t "lcmp-mcp:$IMAGE_TAG" . || {
    warn "Build failed. If it says TasksOperationsNotAllowed, this subscription can't run ACR builds; with Docker Desktop:"
    note "  az acr login -n $ACR && docker build -t $IMAGE . && docker push $IMAGE"
    exit 1
  }
  ok "built lcmp-mcp:$IMAGE_TAG"
}

do_vault() {
  say "Key Vault holding each country's MCP API username and password."
  if [[ -z "$KV_ID" ]]; then
    az keyvault create -g "$RG" -n "$KV" -l "$LOC" --enable-rbac-authorization true -o none || die "Can't create vault $KV: pick another KV name in $CONF."
    KV_ID=$(azq keyvault show -n "$KV" --query id -o tsv); ok "created vault $KV"
  else ok "vault $KV exists"; fi
  if ensure_role "Key Vault Secrets Officer" "$ME" User "$KV_ID"; then note "Waiting a minute for the role to apply..."; sleep 60; fi
  local code c; for code in $(codes); do c=$(lower "$code")
    if [[ -n "$(azq keyvault secret show --vault-name "$KV" -n "lcmp-$c-username" --query id -o tsv)" && \
          -n "$(azq keyvault secret show --vault-name "$KV" -n "lcmp-$c-password" --query id -o tsv)" ]]; then
      ok "$code credentials stored (change them with: $0 credentials $code)"
    else store_credentials "$code"; fi
  done
}

do_identity() {
  say "One managed identity lets the app pull its image and read the secrets, with no passwords in config."
  if [[ -z "$IDENTITY_ID" ]]; then
    az identity create -g "$RG" -n "$IDENTITY" -l "$LOC" -o none
    IDENTITY_ID=$(azq identity show -g "$RG" -n "$IDENTITY" --query id -o tsv)
    IDENTITY_PRINCIPAL=$(azq identity show -g "$RG" -n "$IDENTITY" --query principalId -o tsv)
    ok "created identity $IDENTITY"
  else ok "identity $IDENTITY exists"; fi
  local added=0
  if ensure_role AcrPull "$IDENTITY_PRINCIPAL" ServicePrincipal "$ACR_ID"; then added=1; fi
  if ensure_role "Key Vault Secrets User" "$IDENTITY_PRINCIPAL" ServicePrincipal "$KV_ID"; then added=1; fi
  if (( added )); then note "Waiting 90 s: the app can't start until new roles apply..."; sleep 90; fi
}

do_app() {
  say "The Container App: one replica, always on, Entra-protected, credentials as Key Vault references."
  local secrets envs; mapfile -t secrets < <(app_secret_args); mapfile -t envs < <(app_env_args)
  if [[ -z "$FQDN" ]]; then
    note "Takes a minute or two. If it runs past 5 minutes, check from another window: $0 status"
    az containerapp create -g "$RG" -n "$APP" --environment "$ENV_NAME" \
      --image "$IMAGE" --registry-server "$ACR.azurecr.io" --registry-identity "$IDENTITY_ID" \
      --user-assigned "$IDENTITY_ID" --ingress external --target-port 3000 \
      --min-replicas 1 --max-replicas 1 --cpu 1.0 --memory 2.0Gi \
      --secrets "${secrets[@]}" \
      --env-vars "${envs[@]}" "LCMP_BASE_URL=$BASE_URL" "ENTRA_TENANT_ID=$TENANT_ID" \
        "ENTRA_AUDIENCE=api://$API_APP_ID,$API_APP_ID" ENTRA_REQUIRED_ROLE=LCMP.Read -o none
    FQDN=$(azq containerapp show -g "$RG" -n "$APP" --query properties.configuration.ingress.fqdn -o tsv)
    [[ -n "$FQDN" ]] || die "The app wasn't created; run $0 status to see why."
    ok "created $APP"
  else
    ok "$APP exists"
    local current image
    current=$(azq containerapp show -g "$RG" -n "$APP" \
      --query "properties.template.containers[0].env[?name=='LCMP_MARKETPLACES'].value | [0]" -o tsv)
    if [[ "$current" != "$MARKETPLACES" ]]; then
      az containerapp secret set -g "$RG" -n "$APP" --secrets "${secrets[@]}" -o none
      az containerapp update -g "$RG" -n "$APP" --set-env-vars "${envs[@]}" -o none
      ok "countries changed from ${current:-none} to $MARKETPLACES"
    else ok "countries: $MARKETPLACES"; fi
    image=$(azq containerapp show -g "$RG" -n "$APP" --query "properties.template.containers[0].image" -o tsv)
    [[ "$image" == "$IMAGE" ]] || note "The app runs $image; package.json is at $IMAGE_TAG. Roll it with: $0 update"
  fi
  ok "endpoint https://$FQDN/mcp"
}

do_check() {
  say "Health, refusal without a token, and a ping per country with your token."
  check_endpoint
}

do_copilot() {
  say "Add the server as a tool in Copilot Studio. Fill in:"
  report "Server URL" "https://$FQDN/mcp"
  report "Authentication" "OAuth 2.0, Manual"
  report "Client ID" "$CLIENT_APP_ID"
  report "Client secret" "from your password manager (stage 4)"
  report "Authorization URL" "https://login.microsoftonline.com/$TENANT_ID/oauth2/v2.0/authorize"
  report "Token, Refresh URL" "https://login.microsoftonline.com/$TENANT_ID/oauth2/v2.0/token"
  report "Scopes" "api://$API_APP_ID/access_as_user offline_access"
  open_url "https://copilotstudio.microsoft.com"
  step "Open your agent → Tools → Add a tool → New tool → Model Context Protocol (names change; look for MCP)."
  step "Fill in the fields above and create the tool. Copilot Studio then shows a redirect URL."
  ask REDIRECT_URL "Paste the redirect URL (Enter to skip):"
  if [[ -n "$REDIRECT_URL" ]]; then
    local uris; mapfile -t uris < <(azq ad app show --id "$CLIENT_APP_ID" --query "web.redirectUris[]" -o tsv)
    if printf '%s\n' "${uris[@]}" | grep -qxF "$REDIRECT_URL"; then ok "redirect URL already registered"
    else az ad app update --id "$CLIENT_APP_ID" --web-redirect-uris "${uris[@]}" "$REDIRECT_URL"; ok "redirect URL added"; fi
  fi
  step "Create the connection and sign in."
  step "In the tool's settings set Credentials to use → End user credentials."
  note "With maker credentials every call runs as you: anyone using the agent gets in, and the log names you."
  pause "Done? Press Enter."
}

# ── Other commands ────────────────────────────────────────────────────────

cmd_status() {
  sign_in; resolve
  printf '\n%s%s  lcmp-mcp on Azure%s  %s%s, %s%s\n\n' "$BOLD" "$BLUE" "$RESET" "$DIM" "$SUBSCRIPTION" "$RG" "$RESET"
  report "API app" "${API_APP_ID:+$API_APP_ID ($API_APP_NAME)}" "missing (stage 2)"
  if [[ -n "$API_SP_ID" ]]; then
    report "LCMP.Read holders" "$(azq rest --method GET --uri "https://graph.microsoft.com/v1.0/servicePrincipals/$API_SP_ID/appRoleAssignedTo" \
      --query "join(', ', value[].principalDisplayName)" -o tsv)" "nobody (stage 3)"
  fi
  if [[ -n "$CLIENT_APP_ID" ]]; then
    local ends; ends=$(azq ad app show --id "$CLIENT_APP_ID" --query "passwordCredentials[0].endDateTime" -o tsv)
    if [[ -n "$ends" ]]; then report "client app" "$CLIENT_APP_ID, secret expires ${ends%%T*}"
    else report "client app" "" "$CLIENT_APP_ID, no secret (stage 4)"; fi
    report "admin consent" "$(azq rest --method GET --uri "https://graph.microsoft.com/v1.0/servicePrincipals/$CLIENT_SP_ID/oauth2PermissionGrants" \
      --query "value[?resourceId=='$API_SP_ID'].scope | [0]" -o tsv)" "missing (stage 4)"
  else report "client app" "" "missing (stage 4)"; fi
  report "environment" "$(azq containerapp env show -g "$RG" -n "$ENV_NAME" --query properties.provisioningState -o tsv | sed "s/^./$ENV_NAME: &/")" "missing (stage 5)"
  report "registry" "${ACR_ID:+$ACR, tags: $(azq acr repository show-tags -n "$ACR" --repository lcmp-mcp -o tsv | tr '\n' ' ')}" "missing (stage 5)"
  report "vault" "${KV_ID:+$KV}" "missing (stage 7)"
  local code c kind kv want
  if [[ -n "$KV_ID" ]]; then for code in $(codes); do c=$(lower "$code")
    for kind in username password; do
      kv=$(azq keyvault secret show --vault-name "$KV" -n "lcmp-$c-$kind" --query value -o tsv)
      want=$(envval "LCMP_${code}_$(upper "$kind")")
      if [[ -z "$kv" ]]; then report "$code $kind" "" "missing in vault (stage 7)"
      elif [[ "$kv" == *[[:cntrl:]]* ]]; then report "$code $kind" "" "has invisible characters: $0 credentials $code"
      elif [[ -z "$want" ]]; then report "$code $kind" "stored (nothing in .env to compare)"
      elif [[ "$kv" == "$want" ]]; then report "$code $kind" "stored, matches .env"
      else report "$code $kind" "" "differs from .env: $0 credentials $code"; fi
    done
  done; fi
  report "identity" "${IDENTITY_ID:+$IDENTITY, roles: $(azq role assignment list --assignee "$IDENTITY_PRINCIPAL" --all --query "join(', ', [].roleDefinitionName)" -o tsv)}" "missing (stage 8)"
  if [[ -n "$FQDN" ]]; then
    report "app" "$(azq containerapp show -g "$RG" -n "$APP" --query "join(' ', [properties.provisioningState, properties.template.containers[0].image])" -o tsv)"
    local revs; revs=$(az containerapp revision list -g "$RG" -n "$APP" \
      --query "[?properties.active].join(' ', [name, properties.runningState, to_string(properties.replicas)])" -o tsv 2>&1 | tr -d '\r' || true)
    if [[ "$revs" == *ManagedClusterSuspended* ]]; then report "revision" "" "environment suspended by Azure: see Troubleshooting in docs/deploy-azure.md"
    else report "revision" "$revs" "none active"; fi
    printf '\n  %sLast tool calls%s\n' "$BOLD" "$RESET"
    azq containerapp logs show -g "$RG" -n "$APP" --tail 200 --format text | grep '"tool_call"' | tail -n 5 \
      | sed -E 's/^([0-9T:-]{19})[^{]*/  \1  /' | cut -c1-200 || true
    printf '\n'
  else report "app" "" "missing (stage 9)"; fi
  check_endpoint
  printf '\n'
}

cmd_update() {
  sign_in; resolve
  [[ -n "$FQDN" ]] || die "No app yet: run $0 first."
  if azq acr repository show-tags -n "$ACR" --repository lcmp-mcp -o tsv | grep -qx "$IMAGE_TAG"; then
    die "Image tag $IMAGE_TAG already exists. Bump version in package.json first: the same tag wouldn't roll the app."
  fi
  build_image
  az containerapp update -g "$RG" -n "$APP" --image "$IMAGE" -o none
  ok "app now runs $IMAGE"
  check_endpoint
}

cmd_credentials() {
  [[ -n "${1:-}" ]] || die "Usage: $0 credentials CODE (e.g. CYMA)"
  local code; code=$(upper "$1")
  sign_in; resolve
  store_credentials "$code"
  if [[ -n "$FQDN" ]]; then
    # Re-saving the references makes the app fetch the new values now, not within 30 minutes.
    local secrets; mapfile -t secrets < <(app_secret_args)
    az containerapp secret set -g "$RG" -n "$APP" --secrets "${secrets[@]}" -o none
    restart_app
  fi
}

run_wizard() {
load_conf
case "${1:-deploy}" in
  deploy) ;;
  status) cmd_status; return ;;
  update) cmd_update; return ;;
  credentials) cmd_credentials "${2:-}"; return ;;
  restart) sign_in; resolve; restart_app; return ;;
  help|-h|--help) sed -n '/^# Deploys lcmp-mcp/,/^# Names come/p' "$0" | sed 's/^# \{0,1\}//'; return ;;
  *) die "Unknown command $1. Try: $0 help" ;;
esac

TOTAL_STAGES=11

banner "Deploy lcmp-mcp to Azure"

stage "Sign in and check prerequisites";       do_prereqs;    pause
stage "Entra: API app registration";           do_api_app;    pause
stage "Entra: who may use the server";         do_access;     pause
stage "Entra: Copilot Studio client app";      do_client_app; pause
stage "Logs, environment and registry";        do_hosting;    pause
stage "Server image";                          do_image;      pause
stage "Key Vault and marketplace credentials"; do_vault;      pause
stage "Managed identity";                      do_identity;   pause
stage "Container App";                         do_app;        pause
stage "Check it works";                        do_check;      pause
stage "Connect Copilot Studio";                do_copilot

finish
}

run_wizard "$@"; exit
